import { useRef, useState } from 'react';
import type { FnPartial } from './type';
import { isPromise } from './utils';

export interface SafeRaceOptions {
  /** 中途被丢弃的 Promise 抛出错误  */
  onDiscardedPromiseError?: (e: Error) => void;
  /** 开启能力，默认为true，设置为 false 时将原样返回 */
  enabled?: boolean;
}

/**
 * 创建一个安全的异步函数，多次连续调用，保证响应的结果是最后一次调用的
 *
 * @example
 * const safeFetcher = safeRace(fetcher);
 *
 */
export function safeRace<F extends FnPartial>(
  fetcher: F,
  { onDiscardedPromiseError, enabled = true }: SafeRaceOptions = {},
): F {
  if (!fetcher || !enabled) {
    return fetcher;
  }

  let lastCallResult: unknown = null;
  return ((...args: unknown[]) => {
    const currentCallResult = fetcher(...args);

    lastCallResult = currentCallResult;

    if (!isPromise(currentCallResult)) {
      // release memory
      lastCallResult = null;
      // 返回非promise则立即返回结果
      return currentCallResult;
    }

    return new Promise<unknown>((resolve, reject) => {
      currentCallResult
        .then(data => {
          if (lastCallResult === currentCallResult) {
            resolve(data);
          }
        })
        .catch(err => {
          if (lastCallResult === currentCallResult) {
            reject(err);
          } else {
            onDiscardedPromiseError?.(err);
          }
        })
        .finally(() => {
          if (lastCallResult === currentCallResult) {
            // release memory
            lastCallResult = null;
          }
        });
    });
  }) as F;
}

export function useSafeRace<F extends FnPartial>(fn: F, safeRaceOptions: SafeRaceOptions = {}): F {
  const { enabled = true } = safeRaceOptions;
  const fnRef = useRef(fn);
  fnRef.current = fn;
  const [fetcher] = useState(() => safeRace(async (...args: unknown[]) => fnRef.current?.(...args), safeRaceOptions));

  return !enabled || !fn ? fn : (fetcher as F);
}
